use Psr\Clock\ClockInterface;

final class OtpVerifier
{
    private const TTL_SECONDS = 300;

    public function __construct(private readonly ClockInterface $clock)
    {
    }

    public function issue(string $phone): Otp
    {
        $now = $this->clock->now();          // not new DateTimeImmutable()

        return new Otp(
            phone: $phone,
            code: (string) random_int(100_000, 999_999),
            expiresAt: $now->modify('+'.self::TTL_SECONDS.' seconds'),
        );
    }

    public function isExpired(Otp $otp): bool
    {
        return $this->clock->now() >= $otp->expiresAt;
    }
}

use Symfony\Component\Clock\MockClock;

public function testOtpExpiresAfterFiveMinutes(): void
{
    $clock = new MockClock('2027-03-01 10:00:00', 'UTC');
    $verifier = new OtpVerifier($clock);
    $otp = $verifier->issue('+15555550142');

    $clock->sleep(299);                  // doesn't really sleep: the clock moves 299s
    self::assertFalse($verifier->isExpired($otp));

    $clock->sleep(1);                    // exactly 300 seconds have now passed
    self::assertTrue($verifier->isExpired($otp));
}

