#[Route('/api/profile/sync', methods: ['PUT'])]
public function sync(#[MapRequestPayload] ProfileDto $dto): JsonResponse
{
    $profile = $this->profiles->find($dto->id);

    // picking the "newer" by the client's clock: risky
    if ($dto->updatedAt > $profile->getUpdatedAt()) {
        $profile->replaceWith($dto);        // overwrites the whole row
        $this->em->flush();
    }

    return $this->json(['ok' => true]);
}

#[Route('/api/profile/{id}', methods: ['PATCH'])]
public function update(int $id, #[MapRequestPayload] ProfilePatch $dto): JsonResponse
{
    try {
        $this->em->wrapInTransaction(function () use ($id, $dto): void {
            $p = $this->em->find(Profile::class, $id, LockMode::OPTIMISTIC, $dto->version);
            $p->apply($dto->changedFields());   // only the fields that changed
        });
    } catch (OptimisticLockException) {
        return $this->json(['error' => 'A newer version exists'], 409);
    }

    return $this->json(['ok' => true]);
}

