echo $b->format('H:i T P');     // 01:30 BST +01:00 or 01:30 GMT +00:00

/** @return list<DateTimeImmutable> 0 = gap, 1 = normal, 2 = overlap (earlier first) */
function instantsFor(string $wall, DateTimeZone $zone): array
{
    $naive = new DateTimeImmutable($wall, new DateTimeZone('UTC'));
    $found = [];
    foreach ([-86400, 86400] as $shift) {   // the offset a day before and a day after
        $probe = $naive->setTimestamp($naive->getTimestamp() + $shift);
        $utc = $naive->setTimestamp($naive->getTimestamp() - $zone->getOffset($probe));
        $local = $utc->setTimezone($zone);
        // keep a candidate only if it reads back as the same wall time
        if ($local->format('Y-m-d H:i') === $naive->format('Y-m-d H:i')) {
            $found[$utc->getTimestamp()] = $local;
        }
    }
    ksort($found);
    return array_values($found);
}

function resolve(string $wall, DateTimeZone $zone, bool $earlier = true): DateTimeImmutable
{
    $all = instantsFor($wall, $zone);
    return match (count($all)) {
        0 => throw new DomainException("$wall does not exist in {$zone->getName()}"),
        1 => $all[0],
        default => $earlier ? $all[0] : $all[1],
    };
}

