public function occurrenceUtc(int $weeksAhead): DateTimeImmutable
{
    // turn the stored wall-clock time into a time in the given zone
    $local = new DateTimeImmutable(
        $this->localStart->format('Y-m-d H:i:s'),
        new DateTimeZone($this->timezone),
    );

    // +N weeks in the local zone: the wall clock stays 10:00, even across DST
    return $local->modify("+{$weeksAhead} weeks")
        ->setTimezone(new DateTimeZone('UTC'));
}

final readonly class OtpVerifier
{
    private const GRACE_SECONDS = 5;   // network delay + a slight clock difference

    public function __construct(
        private ClockInterface $clock,
        private OtpRepository $otps,
    ) {
    }

    public function verify(int $userId, string $code): bool
    {
        $otp = $this->otps->findLatestFor($userId);

        if ($otp === null || !hash_equals($otp->getCode(), $code)) {
            return false;
        }

        $lastValid = $otp->getExpiresAt()->modify('+'.self::GRACE_SECONDS.' seconds');

        return $this->clock->now() <= $lastValid;   // the server's clock is the judge
    }
}

final class Deadline
{
    private readonly int $endNs;

    public function __construct(int $budgetMs)
    {
        $this->endNs = hrtime(true) + $budgetMs * 1_000_000;   // monotonic
    }

    public function remainingSeconds(): float
    {
        return max(0.0, ($this->endNs - hrtime(true)) / 1_000_000_000);
    }
}

